    public EventCallback<Product> OnAddToCart { get; set; }
}

@using sv_d23805b92ae3480faddce51e408b227d

<aside class="catalog-filters">
    <h2>Filters</h2>

    <section class="filter-section">
        <h3>Categories</h3>
        @if (Categories.Count == 0)
        {
            <p class="filter-loading">Loading categories…</p>
        }
        else
        {
            @foreach (var category in Categories)
            {
                <label class="filter-checkbox">
                    <input type="checkbox"
                           checked="@IsSelected(category)"
                           @onchange="() => ToggleCategory(category)" />
                    @category
                </label>
            }
        }
    </section>

    <section class="filter-section">
        <h3>Price Range</h3>
        <label class="filter-label">
            Min
            <input type="number" min="0" step="0.01"
                   value="@_minPrice"
                   @onchange="e => _minPrice = ParseDecimal(e.Value)" />
        </label>
        <label class="filter-label">
            Max
            <input type="number" min="0" step="0.01"
                   value="@_maxPrice"
                   @onchange="e => _maxPrice = ParseDecimal(e.Value)" />
        </label>
    </section>

    <section class="filter-section">
        <label class="filter-checkbox">
            <input type="checkbox"
                   checked="@_inStockOnly"
                   @onchange="e => _inStockOnly = (bool)(e.Value ?? false)" />
            In Stock Only
        </label>
    </section>

    <div class="filter-actions">
        <button class="btn-apply" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
    </div>
</aside>

@code {
    [Parameter, EditorRequired]
    public List<string> Categories { get; set; } = [];

    [Parameter]
    public EventCallback<ProductFilter> OnApply { get; set; }

    [Parameter]
    public EventCallback OnClear { get; set; }

    private List<string> _selectedCategories = [];
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;

    private bool IsSelected(string category) => _selectedCategories.Contains(category);

    private void ToggleCategory(string category)
    {
        if (_selectedCategories.Contains(category))
            _selectedCategories.Remove(category);
        else
            _selectedCategories.Add(category);
    }

    private decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            Categories: _selectedCategories.Count > 0 ? new List<string>(_selectedCategories) : null,
            MinPrice: _minPrice,
            MaxPrice: _maxPrice,
            InStockOnly: _inStockOnly
        );
        await OnApply.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        await OnClear.InvokeAsync();
    }
}

@page "/catalog"
@using sv_d23805b92ae3480faddce51e408b227d
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-layout">
    <CatalogFilters Categories="_categories"
                    OnApply="HandleApplyFilters"
                    OnClear="HandleClearFilters" />

    <main class="catalog-main">
        @if (_loading)
        {
            <div class="catalog-loading" aria-live="polite">
                <p>Loading products…</p>
            </div>
        }
        else if (_error is not null)
        {
            <div class="catalog-error" role="alert">
                <p>Something went wrong: @_error</p>
                <button class="btn-retry" @onclick="LoadProducts">Retry</button>
            </div>
        }
        else if (_result is not null && _result.Items.Count == 0)
        {
            <div class="catalog-empty">
                <p>No products found matching your criteria.</p>
            </div>
        }
        else if (_result is not null)
        {
            <CatalogToolbar SortBy="@_sortBy"
                            TotalCount="_result.TotalCount"
                            Page="_result.Page"
                            PageSize="_result.PageSize"
                            OnSortChanged="HandleSortChanged" />

            <ProductGrid Products="_result.Items"
                         OnProductSelected="HandleProductSelected"
                         OnAddToCart="HandleAddToCart" />

            @if (TotalPages > 1)
            {
                <CatalogPagination CurrentPage="_currentPage"
                                   TotalPages="TotalPages"
                                   OnPageChanged="HandlePageChanged" />
            }
        }
    </main>
</div>

@code {
    private List<string> _categories = [];
    private PagedResult<Product>? _result;
    private bool _loading = true;
    private string? _error;

    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private const int PageSize = 12;

    private int TotalPages => _result is null || _result.PageSize == 0
        ? 1
        : (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadCategories();
        await LoadProducts();
    }

    private async Task LoadCategories()
    {
        try
        {
            _categories = await ProductService.GetCategoriesAsync();
        }
        catch
        {
            _categories = [];
        }
    }

    private async Task LoadProducts()
    {
        _loading = true;
        _error = null;

        try
        {
            _result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
            _result = null;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleApplyFilters(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleClearFilters()
    {
        _filter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await LoadProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for cart integration
        return Task.CompletedTask;
    }
}

.catalog-layout {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
}

.catalog-main {
    flex: 1;
    min-width: 0;
}

/* Loading, error, empty states */
.catalog-loading,
.catalog-error,
.catalog-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 3rem 1rem;
    text-align: center;
}

.catalog-error {
    color: #dc3545;
}

.btn-retry {
    margin-top: 1rem;
    padding: 0.5rem 1rem;
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

/* Filters sidebar */
::deep .catalog-filters {
    width: 25%;
    min-width: 200px;
    padding: 1rem;
    border-right: 1px solid #e0e0e0;
}

::deep .filter-section {
    margin-bottom: 1.5rem;
}

::deep .filter-section h3 {
    margin-bottom: 0.5rem;
    font-size: 0.9rem;
    font-weight: 600;
}

::deep .filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.25rem;
    cursor: pointer;
}

::deep .filter-label {
    display: flex;
    flex-direction: column;
    margin-bottom: 0.5rem;
    font-size: 0.85rem;
}

::deep .filter-label input {
    margin-top: 0.25rem;
    padding: 0.35rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    width: 100%;
}

::deep .filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

::deep .btn-apply {
    padding: 0.5rem;
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-clear {
    padding: 0.5rem;
    background: #6c757d;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

/* Toolbar */
::deep .catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.75rem;
    background: #f8f9fa;
    border-radius: 4px;
}

::deep .toolbar-sort {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

::deep .toolbar-sort select {
    padding: 0.35rem 0.5rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

::deep .toolbar-info {
    font-size: 0.9rem;
    color: #555;
}

/* Product Grid */
::deep .product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.25rem;
}

::deep .product-card {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: box-shadow 0.2s;
}

::deep .product-card:hover {
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.1);
}

::deep .product-image {
    height: 160px;
    background: #f0f0f0;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #888;
    font-size: 0.85rem;
}

::deep .product-info {
    padding: 0.75rem;
}

::deep .product-name {
    margin: 0 0 0.25rem;
    font-size: 1rem;
}

::deep .product-price {
    margin: 0 0 0.25rem;
    font-weight: 600;
    color: #2d8a4e;
}

::deep .product-rating {
    color: #f5a623;
    margin-bottom: 0.5rem;
}

::deep .badge-out-of-stock {
    display: inline-block;
    padding: 0.2rem 0.5rem;
    background: #dc3545;
    color: white;
    font-size: 0.75rem;
    border-radius: 4px;
    margin-bottom: 0.5rem;
}

::deep .btn-add-to-cart {
    width: 100%;
    padding: 0.5rem;
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-add-to-cart:disabled {
    background: #adb5bd;
    cursor: not-allowed;
}

/* Pagination */
::deep .catalog-pagination {
    display: flex;
    justify-content: center;
    gap: 0.25rem;
    margin-top: 1.5rem;
    padding: 1rem 0;
}

::deep .btn-page {
    padding: 0.4rem 0.75rem;
    border: 1px solid #dee2e6;
    background: white;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-page:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

::deep .btn-page.active {
    background: #0d6efd;
    color: white;
    border-color: #0d6efd;
}

