    border-radius: 4px;
    width: 100%;
}

::deep .filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

::deep .btn-apply {
    padding: 0.5rem;
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-clear {
    padding: 0.5rem;
    background: #6c757d;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

/* Toolbar */
::deep .catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    padding: 0.75rem;
    background: #f8f9fa;
    border-radius: 4px;
}

::deep .toolbar-sort {
    display: flex;
    align-items: center;
    gap: 0.5rem;
