+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+}
+
+::deep .toolbar-sort select {
+    padding: 0.35rem 0.5rem;
+    border: 1px solid #ccc;
+    border-radius: 4px;
+}
+
+::deep .toolbar-info {
+    font-size: 0.9rem;
+    color: #555;
+}
+
+/* Product Grid */
+::deep .product-grid {
+    display: grid;
+    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
+    gap: 1.25rem;
+}
+
+::deep .product-card {
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    overflow: hidden;
+    cursor: pointer;
+    transition: box-shadow 0.2s;
+}
+
+::deep .product-card:hover {
+    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.1);
+}
+
+::deep .product-image {
+    height: 160px;
+    background: #f0f0f0;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    color: #888;
+    font-size: 0.85rem;
+}
+
+::deep .product-info {
+    padding: 0.75rem;
+}
+
+::deep .product-name {
+    margin: 0 0 0.25rem;
+    font-size: 1rem;
+}
+
+::deep .product-price {
+    margin: 0 0 0.25rem;
+    font-weight: 600;
+    color: #2d8a4e;
+}
+
+::deep .product-rating {
+    color: #f5a623;
+    margin-bottom: 0.5rem;
+}
+
+::deep .badge-out-of-stock {
+    display: inline-block;
+    padding: 0.2rem 0.5rem;
+    background: #dc3545;
+    color: white;
+    font-size: 0.75rem;
+    border-radius: 4px;
+    margin-bottom: 0.5rem;
+}
+
+::deep .btn-add-to-cart {
+    width: 100%;
+    padding: 0.5rem;
+    background: #0d6efd;
+    color: white;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+::deep .btn-add-to-cart:disabled {
+    background: #adb5bd;
+    cursor: not-allowed;
+}
+
+/* Pagination */
+::deep .catalog-pagination {
+    display: flex;
+    justify-content: center;
+    gap: 0.25rem;
+    margin-top: 1.5rem;
+    padding: 1rem 0;
+}
+
+::deep .btn-page {
+    padding: 0.4rem 0.75rem;
+    border: 1px solid #dee2e6;
+    background: white;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+::deep .btn-page:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+::deep .btn-page.active {
+    background: #0d6efd;
+    color: white;
+    border-color: #0d6efd;
+}
+

